        "Giardiniera"@pt ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:LeekTopping ],
        [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:MozzarellaTopping ],
        [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:MushroomTopping ],
        [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:OliveTopping ],
        [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:PeperonataTopping ],
        [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:PetitPoisTopping ],
        [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:SlicedTomatoTopping ],
        [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:TomatoTopping ],
        [ a owl:Restriction ;
            owl:allValuesFrom [ a owl:Class ;
                    owl:unionOf ( ns1:LeekTopping ns1:MozzarellaTopping ns1:MushroomTopping ns1:OliveTopping ns1:PeperonataTopping ns1:PetitPoisTopping ns1:SlicedTomatoTopping ns1:TomatoTopping ) ] ;
            owl:onProperty ns1:hasTopping ],
        ns1:NamedPizza ;
    skos:altLabel "Giardiniera"@en,
        "Giardiniera Pizza"@en ;
    skos:prefLabel "Giardiniera"@en .

