        owl:NamedIndividual ;
    ns1:hasTopping <http://www.co-ode.org/ontologies/pizza/HotGreenPepperTopping_dynamic_1>,
        <http://www.co-ode.org/ontologies/pizza/JalapenoPepperTopping_dynamic_1>,
