<http://www.co-ode.org/ontologies/pizza/Cajun_84> a ns1:NamedPizza,
        owl:NamedIndividual ;
    ns1:hasTopping <http://www.co-ode.org/ontologies/pizza/MozzarellaTopping_dynamic_1>,
        <http://www.co-ode.org/ontologies/pizza/OnionTopping_dynamic_1>,
