        "BaseFinaEQuebradica"@pt ;
    rdfs:subClassOf ns1:PizzaBase ;
    skos:prefLabel "Thin And Crispy Base"@en .

ns1:hasBase a owl:FunctionalProperty,
        owl:InverseFunctionalProperty,
        owl:ObjectProperty ;
    rdfs:domain ns1:Pizza ;
    rdfs:range ns1:PizzaBase ;
    rdfs:subPropertyOf ns1:hasIngredient ;
    owl:inverseOf ns1:isBaseOf .

ns1:isIngredientOf a owl:ObjectProperty,
        owl:TransitiveProperty ;
    rdfs:comment "The inverse property tree to hasIngredient - all subproperties and attributes of the properties should reflect those under hasIngredient."@en .

ns1:FruitTopping a owl:Class ;
    rdfs:label "FruitTopping"@en,
        "CoberturaDeFrutas"@pt ;
    rdfs:subClassOf ns1:PizzaTopping ;
    skos:prefLabel "Fruit"@en .

ns1:GreenPepperTopping a owl:Class ;
    rdfs:label "GreenPepperTopping"@en,
        "CoberturaDePimentaoVerde"@pt ;
    rdfs:subClassOf ns1:PepperTopping ;
    skos:prefLabel "Green Pepper"@en .

ns1:NutTopping a owl:Class ;
    rdfs:label "NutTopping"@en,
        "CoberturaDeCastanha"@pt ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasSpiciness ;
            owl:someValuesFrom ns1:Mild ],
        ns1:PizzaTopping ;
    skos:prefLabel "Nut"@en .

ns1:PizzaBase a owl:Class ;
    rdfs:label "PizzaBase"@en,
        "BaseDaPizza"@pt ;
    rdfs:subClassOf ns1:Food ;
    skos:prefLabel "Pizza Base"@en .

ns1:SauceTopping a owl:Class ;
    rdfs:label "SauceTopping"@en,
        "CoberturaEmMolho"@pt ;
    rdfs:subClassOf ns1:PizzaTopping ;
    skos:prefLabel "Sauce"@en .

ns1:Spiciness a owl:Class ;
    rdfs:label "Spiciness"@en,
        "Tempero"@pt ;
    rdfs:comment "A ValuePartition that describes only values from Hot, Medium or Mild. NB Subclasses can themselves be divided up into further partitions."@en ;
    rdfs:subClassOf ns1:ValuePartition ;
    owl:equivalentClass [ a owl:Class ;
            owl:unionOf ( ns1:Hot ns1:Medium ns1:Mild ) ] ;
    skos:prefLabel "Spiciness"@en .

ns1:FishTopping a owl:Class ;
    rdfs:label "SeafoodTopping"@en,
        "CoberturaDePeixe"@pt ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasSpiciness ;
            owl:someValuesFrom ns1:Mild ],
        ns1:PizzaTopping ;
    skos:prefLabel "Seafood"@en .

ns1:Food a owl:Class ;
    rdfs:label "Food"@en ;
    rdfs:subClassOf ns1:DomainConcept ;
    skos:prefLabel "Food"@en .

ns1:HerbSpiceTopping a owl:Class ;
    rdfs:label "HerbSpiceTopping"@en,
        "CoberturaDeErvas"@pt ;
    rdfs:subClassOf ns1:PizzaTopping ;
    skos:prefLabel "Herb Spice"@en .

ns1:LeekTopping a owl:Class ;
    rdfs:label "LeekTopping"@en,
        "CoberturaDeLeek"@pt ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasSpiciness ;
            owl:someValuesFrom ns1:Mild ],
        ns1:VegetableTopping ;
    skos:prefLabel "Leek"@en .

ns1:PepperTopping a owl:Class ;
    rdfs:label "PepperTopping"@en,
        "CoberturaDePimentao"@pt ;
    rdfs:subClassOf ns1:VegetableTopping ;
    skos:prefLabel "Pepper"@en .

ns1:MeatTopping a owl:Class ;
    rdfs:label "MeatTopping"@en,
        "CoberturaDeCarne"@pt ;
    rdfs:subClassOf ns1:PizzaTopping ;
    skos:prefLabel "Meat"@en .

ns1:PeperonataTopping a owl:Class ;
    rdfs:label "PeperonataTopping"@en,
        "CoberturaPeperonata"@pt ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasSpiciness ;
            owl:someValuesFrom ns1:Medium ],
        ns1:PepperTopping ;
    skos:prefLabel "Peperonata"@en .

ns1:PeperoniSausageTopping a owl:Class ;
    rdfs:label "PeperoniSausageTopping"@en,
        "CoberturaDeCalabreza"@pt ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasSpiciness ;
            owl:someValuesFrom ns1:Medium ],
        ns1:MeatTopping ;
    skos:prefLabel "Peperoni Sausage"@en .

ns1:Medium a owl:Class ;
    rdfs:label "Medium"@en,
        "Media"@pt ;
    rdfs:subClassOf ns1:Spiciness ;
    skos:prefLabel "Medium"@en .

ns1:OnionTopping a owl:Class ;
    rdfs:label "OnionTopping"@en,
        "CoberturaDeCebola"@pt ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasSpiciness ;
            owl:someValuesFrom ns1:Medium ],
        ns1:VegetableTopping ;
    skos:prefLabel "Onion"@en .

ns1:AnchoviesTopping a owl:Class ;
    rdfs:label "AnchoviesTopping"@en,
        "CoberturaDeAnchovies"@pt ;
    rdfs:subClassOf ns1:FishTopping ;
    skos:prefLabel "Anchovies"@en .

ns1:CaperTopping a owl:Class ;
    rdfs:label "CaperTopping"@en,
        "CoberturaDeCaper"@pt ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasSpiciness ;
            owl:someValuesFrom ns1:Mild ],
        ns1:VegetableTopping ;
    skos:prefLabel "Caper"@en .

ns1:CheeseTopping a owl:Class ;
    rdfs:label "CheeseTopping"@en,
        "CoberturaDeQueijo"@pt ;
    rdfs:subClassOf ns1:PizzaTopping ;
    skos:prefLabel "Cheese"@en .

ns1:Hot a owl:Class ;
    rdfs:label "Hot"@en,
        "Picante"@pt ;
    rdfs:subClassOf ns1:Spiciness ;
    skos:prefLabel "Hot"@en .

ns1:MushroomTopping a owl:Class ;
    rdfs:label "MushroomTopping"@en,
        "CoberturaDeCogumelo"@pt ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasSpiciness ;
            owl:someValuesFrom ns1:Mild ],
        ns1:VegetableTopping ;
    skos:prefLabel "Mushroom"@en .

ns1:ParmesanTopping a owl:Class ;
    rdfs:label "ParmezanTopping"@en,
        "CoberturaDeParmesao"@pt ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasSpiciness ;
            owl:someValuesFrom ns1:Mild ],
        ns1:CheeseTopping ;
    skos:prefLabel "Parmezan"@en .

ns1:HamTopping a owl:Class ;
    rdfs:label "HamTopping"@en,
        "CoberturaDePresunto"@pt ;
    rdfs:subClassOf ns1:MeatTopping ;
    skos:prefLabel "Ham"@en .

ns1:GarlicTopping a owl:Class ;
    rdfs:label "GarlicTopping"@en,
        "CoberturaDeAlho"@pt ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasSpiciness ;
            owl:someValuesFrom ns1:Medium ],
        ns1:VegetableTopping ;
    skos:prefLabel "Garlic"@en .

ns1:PizzaTopping a owl:Class ;
    rdfs:label "PizzaTopping"@en,
        "CoberturaDaPizza"@pt ;
    rdfs:subClassOf ns1:Food ;
    skos:prefLabel "Pizza Topping"@en .

ns1:Pizza a owl:Class ;
    rdfs:label "Pizza"@en ;
    rdfs:seeAlso <https://en.wikipedia.org/wiki/Pizza> ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasBase ;
            owl:someValuesFrom ns1:PizzaBase ],
        ns1:Food ;
    skos:prefLabel "Pizza"@en .

ns1:VegetableTopping a owl:Class ;
    rdfs:label "VegetableTopping"@en,
        "CoberturaDeVegetais"@pt ;
    rdfs:subClassOf ns1:PizzaTopping ;
    skos:prefLabel "Vegetable Topping"@en .

ns1:OliveTopping a owl:Class ;
    rdfs:label "OliveTopping"@en,
        "CoberturaDeAzeitona"@pt ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasSpiciness ;
            owl:someValuesFrom ns1:Mild ],
        ns1:VegetableTopping ;
    skos:prefLabel "Olive"@en .

ns1:NamedPizza a owl:Class ;
    rdfs:label "PizzaComUmNome"@pt ;
    rdfs:comment "A pizza that can be found on a pizza menu"@en ;
    rdfs:subClassOf ns1:Pizza .

ns1:Mild a owl:Class ;
    rdfs:label "Mild"@en,
        "NaoPicante"@pt ;
    rdfs:subClassOf ns1:Spiciness ;
    skos:prefLabel "Mild"@en .

ns1:hasSpiciness a owl:FunctionalProperty,
        owl:ObjectProperty ;
    rdfs:comment "A property created to be used with the ValuePartition - Spiciness."@en ;
    rdfs:range ns1:Spiciness .

ns1:MozzarellaTopping a owl:Class ;
    rdfs:label "MozzarellaTopping"@en,
        "CoberturaDeMozzarella"@pt ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasSpiciness ;
            owl:someValuesFrom ns1:Mild ],
        ns1:CheeseTopping ;
    skos:prefLabel "Mozzarella"@en .

ns1:TomatoTopping a owl:Class ;
    rdfs:label "TomatoTopping"@en,
        "CoberturaDeTomate"@pt ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasSpiciness ;
            owl:someValuesFrom ns1:Mild ],
        ns1:VegetableTopping ;
    skos:prefLabel "Tomato"@en .

ns1:hasTopping a owl:InverseFunctionalProperty,
        owl:ObjectProperty ;
    rdfs:comment "Note that hasTopping is inverse functional because isToppingOf is functional"@en ;
    rdfs:domain ns1:Pizza ;
    rdfs:range ns1:PizzaTopping ;
    rdfs:subPropertyOf ns1:hasIngredient ;
    owl:inverseOf ns1:isToppingOf .

[] a owl:AllDisjointClasses ;
    owl:members ( ns1:American ns1:AmericanHot ns1:Cajun ns1:Capricciosa ns1:Caprina ns1:Fiorentina ns1:FourSeasons ns1:FruttiDiMare ns1:Giardiniera ns1:LaReine ns1:Margherita ns1:Mushroom ns1:Napoletana ns1:Parmense ns1:PolloAdAstra ns1:PrinceCarlo ns1:QuattroFormaggi ns1:Rosa ns1:Siciliana ns1:SloppyGiuseppe ns1:Soho ns1:UnclosedPizza ns1:Veneziana ) .

[] a owl:AllDisjointClasses ;
    owl:members ( ns1:AnchoviesTopping ns1:MixedSeafoodTopping ns1:PrawnsTopping ) .

[] a owl:AllDisjointClasses ;
    owl:members ( ns1:ArtichokeTopping ns1:AsparagusTopping ns1:CaperTopping ns1:GarlicTopping ns1:LeekTopping ns1:MushroomTopping ns1:OliveTopping ns1:OnionTopping ns1:PepperTopping ns1:PetitPoisTopping ns1:RocketTopping ns1:SpinachTopping ns1:TomatoTopping ) .

[] a owl:AllDisjointClasses ;
    owl:members ( ns1:CheeseTopping ns1:FishTopping ns1:FruitTopping ns1:HerbSpiceTopping ns1:MeatTopping ns1:NutTopping ns1:SauceTopping ns1:VegetableTopping ) .

[] a owl:AllDisjointClasses ;
    owl:members ( ns1:ChickenTopping ns1:HamTopping ns1:HotSpicedBeefTopping ns1:PeperoniSausageTopping ) .

