            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:JalapenoPepperTopping ],
        [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:MozzarellaTopping ],
        [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:PeperoniSausageTopping ],
        [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:TomatoTopping ],
        [ a owl:Restriction ;
            owl:allValuesFrom [ a owl:Class ;
                    owl:unionOf ( ns1:HotGreenPepperTopping ns1:JalapenoPepperTopping ns1:MozzarellaTopping ns1:PeperoniSausageTopping ns1:TomatoTopping ) ] ;
            owl:onProperty ns1:hasTopping ],
        [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:HotGreenPepperTopping ],
        ns1:NamedPizza ;
    skos:altLabel "American Hot"@en,
        "American Hot Pizza"@en ;
    skos:prefLabel "American Hot"@en .

ns1:Cajun a owl:Class ;
    rdfs:label "Cajun"@en,
        "Cajun"@pt ;
