<http://www.co-ode.org/ontologies/pizza/FourSeasons_88> a ns1:NamedPizza,
        owl:NamedIndividual ;
    ns1:hasTopping <http://www.co-ode.org/ontologies/pizza/AnchoviesTopping_dynamic_1>,
        <http://www.co-ode.org/ontologies/pizza/CaperTopping_dynamic_1>,
