<http://www.co-ode.org/ontologies/pizza/Giardiniera_56> a ns1:NamedPizza,
        owl:NamedIndividual ;
    ns1:hasTopping <http://www.co-ode.org/ontologies/pizza/LeekTopping_dynamic_1>,
        <http://www.co-ode.org/ontologies/pizza/MozzarellaTopping_dynamic_1>,
        <http://www.co-ode.org/ontologies/pizza/MushroomTopping_dynamic_1>,
