<http://example.org/extracted/1hop/Napoletana_29> a owl:Ontology ;
    rdfs:label "OWL2Bench Individual Subgraph (1-hop)"@en ;
    rdfs:comment "A Benchmark for OWL 2 Ontologies. Individual-centered 1-hop extraction." ;
    owl:versionInfo "OWL2Bench, ver 2020" .

dc:description a owl:AnnotationProperty .

dc:title a owl:AnnotationProperty .

dcterms:contributor a owl:AnnotationProperty .

dcterms:license a owl:AnnotationProperty .

