        "BaseFinaEQuebradica"@pt ;
    rdfs:subClassOf ns1:PizzaBase ;
    skos:prefLabel "Thin And Crispy Base"@en .

ns1:hasBase a owl:FunctionalProperty,
        owl:InverseFunctionalProperty,
        owl:ObjectProperty ;
    rdfs:domain ns1:Pizza ;
    rdfs:range ns1:PizzaBase ;
    rdfs:subPropertyOf ns1:hasIngredient ;
    owl:inverseOf ns1:isBaseOf .

ns1:isIngredientOf a owl:ObjectProperty,
        owl:TransitiveProperty ;
    rdfs:comment "The inverse property tree to hasIngredient - all subproperties and attributes of the properties should reflect those under hasIngredient."@en .

ns1:FruitTopping a owl:Class ;
    rdfs:label "FruitTopping"@en,
        "CoberturaDeFrutas"@pt ;
    rdfs:subClassOf ns1:PizzaTopping ;
    skos:prefLabel "Fruit"@en .

ns1:GreenPepperTopping a owl:Class ;
    rdfs:label "GreenPepperTopping"@en,
        "CoberturaDePimentaoVerde"@pt ;
    rdfs:subClassOf ns1:PepperTopping ;
    skos:prefLabel "Green Pepper"@en .

ns1:NutTopping a owl:Class ;
    rdfs:label "NutTopping"@en,
        "CoberturaDeCastanha"@pt ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasSpiciness ;
            owl:someValuesFrom ns1:Mild ],
        ns1:PizzaTopping ;
    skos:prefLabel "Nut"@en .

ns1:PizzaBase a owl:Class ;
    rdfs:label "PizzaBase"@en,
        "BaseDaPizza"@pt ;
    rdfs:subClassOf ns1:Food ;
    skos:prefLabel "Pizza Base"@en .

ns1:SauceTopping a owl:Class ;
    rdfs:label "SauceTopping"@en,
        "CoberturaEmMolho"@pt ;
    rdfs:subClassOf ns1:PizzaTopping ;
    skos:prefLabel "Sauce"@en .

ns1:Spiciness a owl:Class ;
    rdfs:label "Spiciness"@en,
        "Tempero"@pt ;
    rdfs:comment "A ValuePartition that describes only values from Hot, Medium or Mild. NB Subclasses can themselves be divided up into further partitions."@en ;
    rdfs:subClassOf ns1:ValuePartition ;
    owl:equivalentClass [ a owl:Class ;
            owl:unionOf ( ns1:Hot ns1:Medium ns1:Mild ) ] ;
    skos:prefLabel "Spiciness"@en .

ns1:FishTopping a owl:Class ;
    rdfs:label "SeafoodTopping"@en,
        "CoberturaDePeixe"@pt ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasSpiciness ;
            owl:someValuesFrom ns1:Mild ],
        ns1:PizzaTopping ;
    skos:prefLabel "Seafood"@en .

ns1:Food a owl:Class ;
    rdfs:label "Food"@en ;
    rdfs:subClassOf ns1:DomainConcept ;
    skos:prefLabel "Food"@en .

ns1:HerbSpiceTopping a owl:Class ;
    rdfs:label "HerbSpiceTopping"@en,
        "CoberturaDeErvas"@pt ;
    rdfs:subClassOf ns1:PizzaTopping ;
    skos:prefLabel "Herb Spice"@en .

ns1:LeekTopping a owl:Class ;
    rdfs:label "LeekTopping"@en,
        "CoberturaDeLeek"@pt ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasSpiciness ;
            owl:someValuesFrom ns1:Mild ],
        ns1:VegetableTopping ;
    skos:prefLabel "Leek"@en .

ns1:PepperTopping a owl:Class ;
    rdfs:label "PepperTopping"@en,
        "CoberturaDePimentao"@pt ;
    rdfs:subClassOf ns1:VegetableTopping ;
    skos:prefLabel "Pepper"@en .

ns1:MeatTopping a owl:Class ;
    rdfs:label "MeatTopping"@en,
        "CoberturaDeCarne"@pt ;
    rdfs:subClassOf ns1:PizzaTopping ;
    skos:prefLabel "Meat"@en .

ns1:PeperonataTopping a owl:Class ;
    rdfs:label "PeperonataTopping"@en,
        "CoberturaPeperonata"@pt ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasSpiciness ;
            owl:someValuesFrom ns1:Medium ],
        ns1:PepperTopping ;
    skos:prefLabel "Peperonata"@en .

ns1:PeperoniSausageTopping a owl:Class ;
    rdfs:label "PeperoniSausageTopping"@en,
        "CoberturaDeCalabreza"@pt ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasSpiciness ;
            owl:someValuesFrom ns1:Medium ],
        ns1:MeatTopping ;
    skos:prefLabel "Peperoni Sausage"@en .

ns1:Medium a owl:Class ;
    rdfs:label "Medium"@en,
        "Media"@pt ;
    rdfs:subClassOf ns1:Spiciness ;
    skos:prefLabel "Medium"@en .

ns1:OnionTopping a owl:Class ;
    rdfs:label "OnionTopping"@en,
        "CoberturaDeCebola"@pt ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasSpiciness ;
            owl:someValuesFrom ns1:Medium ],
        ns1:VegetableTopping ;
    skos:prefLabel "Onion"@en .

ns1:AnchoviesTopping a owl:Class ;
    rdfs:label "AnchoviesTopping"@en,
        "CoberturaDeAnchovies"@pt ;
    rdfs:subClassOf ns1:FishTopping ;
    skos:prefLabel "Anchovies"@en .

ns1:CaperTopping a owl:Class ;
    rdfs:label "CaperTopping"@en,
        "CoberturaDeCaper"@pt ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasSpiciness ;
            owl:someValuesFrom ns1:Mild ],
        ns1:VegetableTopping ;
    skos:prefLabel "Caper"@en .

ns1:CheeseTopping a owl:Class ;
    rdfs:label "CheeseTopping"@en,
        "CoberturaDeQueijo"@pt ;
    rdfs:subClassOf ns1:PizzaTopping ;
    skos:prefLabel "Cheese"@en .

ns1:Hot a owl:Class ;
    rdfs:label "Hot"@en,
        "Picante"@pt ;
    rdfs:subClassOf ns1:Spiciness ;
    skos:prefLabel "Hot"@en .

ns1:MushroomTopping a owl:Class ;
    rdfs:label "MushroomTopping"@en,
        "CoberturaDeCogumelo"@pt ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasSpiciness ;
            owl:someValuesFrom ns1:Mild ],
        ns1:VegetableTopping ;
    skos:prefLabel "Mushroom"@en .

ns1:ParmesanTopping a owl:Class ;
    rdfs:label "ParmezanTopping"@en,
        "CoberturaDeParmesao"@pt ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasSpiciness ;
            owl:someValuesFrom ns1:Mild ],
        ns1:CheeseTopping ;
    skos:prefLabel "Parmezan"@en .

ns1:HamTopping a owl:Class ;
    rdfs:label "HamTopping"@en,
        "CoberturaDePresunto"@pt ;
    rdfs:subClassOf ns1:MeatTopping ;
    skos:prefLabel "Ham"@en .

ns1:GarlicTopping a owl:Class ;
    rdfs:label "GarlicTopping"@en,
        "CoberturaDeAlho"@pt ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasSpiciness ;
            owl:someValuesFrom ns1:Medium ],
        ns1:VegetableTopping ;
    skos:prefLabel "Garlic"@en .

ns1:PizzaTopping a owl:Class ;
    rdfs:label "PizzaTopping"@en,
        "CoberturaDaPizza"@pt ;
    rdfs:subClassOf ns1:Food ;
    skos:prefLabel "Pizza Topping"@en .

ns1:Pizza a owl:Class ;
    rdfs:label "Pizza"@en ;
    rdfs:seeAlso <https://en.wikipedia.org/wiki/Pizza> ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasBase ;
            owl:someValuesFrom ns1:PizzaBase ],
        ns1:Food ;
    skos:prefLabel "Pizza"@en .

ns1:VegetableTopping a owl:Class ;
    rdfs:label "VegetableTopping"@en,
        "CoberturaDeVegetais"@pt ;
    rdfs:subClassOf ns1:PizzaTopping ;
    skos:prefLabel "Vegetable Topping"@en .

ns1:OliveTopping a owl:Class ;
    rdfs:label "OliveTopping"@en,
        "CoberturaDeAzeitona"@pt ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasSpiciness ;
            owl:someValuesFrom ns1:Mild ],
        ns1:VegetableTopping ;
    skos:prefLabel "Olive"@en .

ns1:NamedPizza a owl:Class ;
    rdfs:label "PizzaComUmNome"@pt ;
    rdfs:comment "A pizza that can be found on a pizza menu"@en ;
    rdfs:subClassOf ns1:Pizza .

ns1:Mild a owl:Class ;
    rdfs:label "Mild"@en,
        "NaoPicante"@pt ;
    rdfs:subClassOf ns1:Spiciness ;
    skos:prefLabel "Mild"@en .

ns1:hasSpiciness a owl:FunctionalProperty,
        owl:ObjectProperty ;
    rdfs:comment "A property created to be used with the ValuePartition - Spiciness."@en ;
    rdfs:range ns1:Spiciness .

ns1:MozzarellaTopping a owl:Class ;
    rdfs:label "MozzarellaTopping"@en,
        "CoberturaDeMozzarella"@pt ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasSpiciness ;
            owl:someValuesFrom ns1:Mild ],
        ns1:CheeseTopping ;
    skos:prefLabel "Mozzarella"@en .

ns1:TomatoTopping a owl:Class ;
    rdfs:label "TomatoTopping"@en,
        "CoberturaDeTomate"@pt ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasSpiciness ;
            owl:someValuesFrom ns1:Mild ],
        ns1:VegetableTopping ;
    skos:prefLabel "Tomato"@en .

ns1:hasTopping a owl:InverseFunctionalProperty,
        owl:ObjectProperty ;
    rdfs:comment "Note that hasTopping is inverse functional because isToppingOf is functional"@en ;
    rdfs:domain ns1:Pizza ;
    rdfs:range ns1:PizzaTopping ;
    rdfs:subPropertyOf ns1:hasIngredient ;
    owl:inverseOf ns1:isToppingOf .

[] a owl:AllDisjointClasses ;
    owl:members ( ns1:American ns1:AmericanHot ns1:Cajun ns1:Capricciosa ns1:Caprina ns1:Fiorentina ns1:FourSeasons ns1:FruttiDiMare ns1:Giardiniera ns1:LaReine ns1:Margherita ns1:Mushroom ns1:Napoletana ns1:Parmense ns1:PolloAdAstra ns1:PrinceCarlo ns1:QuattroFormaggi ns1:Rosa ns1:Siciliana ns1:SloppyGiuseppe ns1:Soho ns1:UnclosedPizza ns1:Veneziana ) .

[] a owl:AllDisjointClasses ;
    owl:members ( ns1:AnchoviesTopping ns1:MixedSeafoodTopping ns1:PrawnsTopping ) .

[] a owl:AllDisjointClasses ;
    owl:members ( ns1:ArtichokeTopping ns1:AsparagusTopping ns1:CaperTopping ns1:GarlicTopping ns1:LeekTopping ns1:MushroomTopping ns1:OliveTopping ns1:OnionTopping ns1:PepperTopping ns1:PetitPoisTopping ns1:RocketTopping ns1:SpinachTopping ns1:TomatoTopping ) .

[] a owl:AllDisjointClasses ;
    owl:members ( ns1:CheeseTopping ns1:FishTopping ns1:FruitTopping ns1:HerbSpiceTopping ns1:MeatTopping ns1:NutTopping ns1:SauceTopping ns1:VegetableTopping ) .

[] a owl:AllDisjointClasses ;
    owl:members ( ns1:ChickenTopping ns1:HamTopping ns1:HotSpicedBeefTopping ns1:PeperoniSausageTopping ) .

[] a owl:AllDisjointClasses ;
    owl:members ( ns1:FourCheesesTopping ns1:GoatsCheeseTopping ns1:GorgonzolaTopping ns1:MozzarellaTopping ns1:ParmesanTopping ) .

[] a owl:AllDisjointClasses ;
    owl:members ( ns1:GreenPepperTopping ns1:JalapenoPepperTopping ns1:PeperonataTopping ns1:SweetPepperTopping ) .

[] a owl:AllDisjointClasses ;
    owl:members ( ns1:Hot ns1:Medium ns1:Mild ) .

@prefix dc: <http://purl.org/dc/elements/1.1/> .
@prefix dcterms: <http://purl.org/dc/terms/> .
@prefix ns1: <http://www.co-ode.org/ontologies/pizza/pizza.owl#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/extracted/1hop/Parmense_64> a owl:Ontology ;
    rdfs:label "OWL2Bench Individual Subgraph (1-hop)"@en ;
    rdfs:comment "A Benchmark for OWL 2 Ontologies. Individual-centered 1-hop extraction." ;
    owl:versionInfo "OWL2Bench, ver 2020" .

dc:description a owl:AnnotationProperty .

dc:title a owl:AnnotationProperty .

dcterms:contributor a owl:AnnotationProperty .

dcterms:license a owl:AnnotationProperty .

dcterms:provenance a owl:AnnotationProperty .

<http://www.co-ode.org/ontologies/pizza/Parmense_64> a ns1:NamedPizza,
        owl:NamedIndividual ;
    ns1:hasTopping <http://www.co-ode.org/ontologies/pizza/AsparagusTopping_dynamic_1>,
        <http://www.co-ode.org/ontologies/pizza/HamTopping_dynamic_1>,
        <http://www.co-ode.org/ontologies/pizza/MozzarellaTopping_dynamic_1>,
        <http://www.co-ode.org/ontologies/pizza/ParmesanTopping_dynamic_1>,
        <http://www.co-ode.org/ontologies/pizza/TomatoTopping_dynamic_1> .

ns1:CheeseyPizza a owl:Class ;
    rdfs:label "CheesyPizza"@en,
        "PizzaComQueijo"@pt ;
    owl:equivalentClass [ a owl:Class ;
            owl:intersectionOf ( ns1:Pizza [ a owl:Restriction ;
                        owl:onProperty ns1:hasTopping ;
                        owl:someValuesFrom ns1:CheeseTopping ] ) ] ;
    skos:definition "Any pizza that has at least 1 cheese topping."@en ;
    skos:prefLabel "Cheesy Pizza"@en .

ns1:Country a owl:Class ;
    rdfs:label "Country"@en,
        "Pais"@pt ;
    rdfs:comment "A class that is equivalent to the set of individuals that are described in the enumeration - ie Countries can only be either America, England, France, Germany or Italy and nothing else. Note that these individuals have been asserted to be allDifferent from each other."@en ;
    skos:prefLabel "Country"@en .

ns1:DeepPanBase a owl:Class ;
    rdfs:label "DeepPanBase"@en,
        "BaseEspessa"@pt ;
    rdfs:subClassOf ns1:PizzaBase ;
    owl:disjointWith ns1:ThinAndCrispyBase ;
    skos:prefLabel "Deep Pan Base"@en .

ns1:InterestingPizza a owl:Class ;
    rdfs:label "InterestingPizza"@en,
        "PizzaInteressante"@pt ;
    owl:equivalentClass [ a owl:Class ;
            owl:intersectionOf ( ns1:Pizza [ a owl:Restriction ;
                        owl:minCardinality "3"^^xsd:nonNegativeInteger ;
                        owl:onProperty ns1:hasTopping ] ) ] ;
    skos:definition "Any pizza that has at least 3 toppings. Note that this is a cardinality constraint on the hasTopping property and NOT a qualified cardinality constraint (QCR). A QCR would specify from which class the members in this relationship must be. eg has at least 3 toppings from PizzaTopping. This is currently not supported in OWL."@en ;
    skos:prefLabel "Interesting Pizza"@en .

ns1:MeatyPizza a owl:Class ;
    rdfs:label "MeatyPizza"@en,
        "PizzaDeCarne"@pt ;
    owl:equivalentClass [ a owl:Class ;
            owl:intersectionOf ( ns1:Pizza [ a owl:Restriction ;
                        owl:onProperty ns1:hasTopping ;
                        owl:someValuesFrom ns1:MeatTopping ] ) ] ;
    skos:definition "Any pizza that has at least one meat topping"@en ;
    skos:prefLabel "Meaty Pizza"@en .

ns1:NonVegetarianPizza a owl:Class ;
    rdfs:label "NonVegetarianPizza"@en,
        "PizzaNaoVegetariana"@pt ;
    owl:disjointWith ns1:VegetarianPizza ;
    owl:equivalentClass [ a owl:Class ;
            owl:intersectionOf ( ns1:Pizza [ a owl:Class ;
                        owl:complementOf ns1:VegetarianPizza ] ) ] ;
    skos:definition "Any Pizza that is not a VegetarianPizza"@en ;
    skos:prefLabel "Non Vegetarian Pizza"@en .

ns1:ParmaHamTopping a owl:Class ;
    rdfs:label "ParmaHamTopping"@en,
        "CoberturaDePrezuntoParma"@pt ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasSpiciness ;
            owl:someValuesFrom ns1:Mild ],
        ns1:HamTopping ;
    skos:prefLabel "Parma Ham"@en .

ns1:RealItalianPizza a owl:Class ;
    rdfs:label "RealItalianPizza"@en,
        "PizzaItalianaReal"@pt ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:allValuesFrom ns1:ThinAndCrispyBase ;
            owl:onProperty ns1:hasBase ] ;
    skos:definition "Any Pizza that has the country of origin, Italy.  RealItalianPizzas must also only have ThinAndCrispy bases."@en ;
    skos:prefLabel "Real Italian Pizza"@en .

ns1:SpicyPizza a owl:Class ;
    rdfs:label "SpicyPizza"@en,
        "PizzaTemperada"@pt ;
    owl:equivalentClass [ a owl:Class ;
            owl:intersectionOf ( ns1:Pizza [ a owl:Restriction ;
                        owl:onProperty ns1:hasTopping ;
                        owl:someValuesFrom ns1:SpicyTopping ] ) ] ;
    skos:definition "Any pizza that has a spicy topping is a SpicyPizza"@en ;
    skos:prefLabel "Spicy Pizza"@en .

ns1:SpicyPizzaEquivalent a owl:Class ;
    rdfs:label "SpicyPizzaEquivalent"@en,
        "PizzaTemperadaEquivalente"@pt ;
    rdfs:comment "An alternative definition for the SpicyPizza which does away with needing a definition of SpicyTopping and uses a slightly more complicated restriction: Pizzas that have at least one topping that is both a PizzaTopping and has spiciness hot are members of this class."@en ;
    owl:equivalentClass [ a owl:Class ;
            owl:intersectionOf ( ns1:Pizza [ a owl:Restriction ;
                        owl:onProperty ns1:hasTopping ;
                        owl:someValuesFrom [ a owl:Class ;
                                owl:intersectionOf ( ns1:PizzaTopping [ a owl:Restriction ;
                                            owl:onProperty ns1:hasSpiciness ;
                                            owl:someValuesFrom ns1:Hot ] ) ] ] ) ] ;
    skos:prefLabel "Spicy Pizza Equivalent"@en .

ns1:ThinAndCrispyPizza a owl:Class ;
    rdfs:label "ThinAndCrispyPizza"@en ;
    owl:equivalentClass [ a owl:Class ;
            owl:intersectionOf ( ns1:Pizza [ a owl:Restriction ;
                        owl:allValuesFrom ns1:ThinAndCrispyBase ;
                        owl:onProperty ns1:hasBase ] ) ] ;
    skos:prefLabel "Thin And Crispy Pizza"@en .

ns1:VegetarianPizzaEquivalent1 a owl:Class ;
    rdfs:label "VegetarianPizza1"@en,
        "PizzaVegetarianaEquivalente1"@pt ;
    rdfs:comment "Any pizza that only has vegetarian toppings or no toppings is a VegetarianPizzaEquiv1. Should be inferred to be equivalent to VegetarianPizzaEquiv2.  Not equivalent to VegetarianPizza because PizzaTopping is not covering"@en ;
    owl:equivalentClass [ a owl:Class ;
            owl:intersectionOf ( ns1:Pizza [ a owl:Restriction ;
                        owl:allValuesFrom ns1:VegetarianTopping ;
                        owl:onProperty ns1:hasTopping ] ) ] ;
    skos:prefLabel "Vegetarian Pizza1"@en .

ns1:VegetarianPizzaEquivalent2 a owl:Class ;
    rdfs:label "VegetarianPizza2"@en,
        "PizzaVegetarianaEquivalente2"@pt ;
    rdfs:comment "An alternative to VegetarianPizzaEquiv1 that does not require a definition of VegetarianTopping. Perhaps more difficult to maintain. Not equivalent to VegetarianPizza"@en ;
    owl:equivalentClass [ a owl:Class ;
            owl:intersectionOf ( ns1:Pizza [ a owl:Restriction ;
                        owl:allValuesFrom [ a owl:Class ;
                                owl:unionOf ( ns1:CheeseTopping ns1:FruitTopping ns1:HerbSpiceTopping ns1:NutTopping ns1:SauceTopping ns1:VegetableTopping ) ] ;
                        owl:onProperty ns1:hasTopping ] ) ] ;
    skos:prefLabel "Vegetarian Pizza2"@en .

ns1:hasCountryOfOrigin a owl:ObjectProperty ;
    owl:propertyDisjointWith ns1:hasSpiciness .

skos:altLabel a owl:AnnotationProperty .

skos:definition a owl:AnnotationProperty .

skos:prefLabel a owl:AnnotationProperty .

<http://www.co-ode.org/ontologies/pizza/AsparagusTopping_dynamic_1> a owl:NamedIndividual .

<http://www.co-ode.org/ontologies/pizza/HamTopping_dynamic_1> a owl:NamedIndividual .

<http://www.co-ode.org/ontologies/pizza/MozzarellaTopping_dynamic_1> a owl:NamedIndividual .

<http://www.co-ode.org/ontologies/pizza/ParmesanTopping_dynamic_1> a owl:NamedIndividual .

<http://www.co-ode.org/ontologies/pizza/TomatoTopping_dynamic_1> a owl:NamedIndividual .

ns1:American a owl:Class ;
    rdfs:label "American"@en,
        "Americana"@pt ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:MozzarellaTopping ],
        [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:PeperoniSausageTopping ],
        [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:TomatoTopping ],
        [ a owl:Restriction ;
            owl:allValuesFrom [ a owl:Class ;
                    owl:unionOf ( ns1:MozzarellaTopping ns1:PeperoniSausageTopping ns1:TomatoTopping ) ] ;
            owl:onProperty ns1:hasTopping ],
        ns1:NamedPizza ;
    skos:altLabel "American"@en,
        "American Pizza"@en ;
    skos:prefLabel "American"@en .

ns1:AmericanHot a owl:Class ;
    rdfs:label "AmericanHot"@en,
        "AmericanaPicante"@pt ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:JalapenoPepperTopping ],
        [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:MozzarellaTopping ],
        [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:PeperoniSausageTopping ],
        [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:TomatoTopping ],
        [ a owl:Restriction ;
            owl:allValuesFrom [ a owl:Class ;
                    owl:unionOf ( ns1:HotGreenPepperTopping ns1:JalapenoPepperTopping ns1:MozzarellaTopping ns1:PeperoniSausageTopping ns1:TomatoTopping ) ] ;
            owl:onProperty ns1:hasTopping ],
        [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:HotGreenPepperTopping ],
        ns1:NamedPizza ;
    skos:altLabel "American Hot"@en,
        "American Hot Pizza"@en ;
    skos:prefLabel "American Hot"@en .

ns1:Cajun a owl:Class ;
    rdfs:label "Cajun"@en,
        "Cajun"@pt ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:MozzarellaTopping ],
        [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:OnionTopping ],
        [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:PeperonataTopping ],
        [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:PrawnsTopping ],
        [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:TobascoPepperSauce ],
        [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
