    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasSpiciness ;
            owl:someValuesFrom ns1:Mild ],
        ns1:TomatoTopping ;
    owl:disjointWith ns1:SundriedTomatoTopping ;
    skos:prefLabel "Sliced Tomato"@en .

ns1:SultanaTopping a owl:Class ;
