<http://www.co-ode.org/ontologies/pizza/PrinceCarlo_4> a ns1:NamedPizza,
        owl:NamedIndividual ;
    ns1:hasTopping <http://www.co-ode.org/ontologies/pizza/LeekTopping_dynamic_1>,
