@prefix dc: <http://purl.org/dc/elements/1.1/> .
@prefix dcterms: <http://purl.org/dc/terms/> .
@prefix ns1: <http://www.co-ode.org/ontologies/pizza/pizza.owl#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/extracted/1hop/PrinceCarlo_44> a owl:Ontology ;
    rdfs:label "OWL2Bench Individual Subgraph (1-hop)"@en ;
    rdfs:comment "A Benchmark for OWL 2 Ontologies. Individual-centered 1-hop extraction." ;
    owl:versionInfo "OWL2Bench, ver 2020" .

dc:description a owl:AnnotationProperty .

dc:title a owl:AnnotationProperty .

dcterms:contributor a owl:AnnotationProperty .

dcterms:license a owl:AnnotationProperty .

dcterms:provenance a owl:AnnotationProperty .

<http://www.co-ode.org/ontologies/pizza/PrinceCarlo_44> a ns1:NamedPizza,
        owl:NamedIndividual ;
    ns1:hasTopping <http://www.co-ode.org/ontologies/pizza/LeekTopping_dynamic_1>,
        <http://www.co-ode.org/ontologies/pizza/MozzarellaTopping_dynamic_1>,
        <http://www.co-ode.org/ontologies/pizza/ParmesanTopping_dynamic_1>,
        <http://www.co-ode.org/ontologies/pizza/RosemaryTopping_dynamic_1>,
        <http://www.co-ode.org/ontologies/pizza/TomatoTopping_dynamic_1> .

ns1:CheeseyPizza a owl:Class ;
    rdfs:label "CheesyPizza"@en,
        "PizzaComQueijo"@pt ;
    owl:equivalentClass [ a owl:Class ;
            owl:intersectionOf ( ns1:Pizza [ a owl:Restriction ;
                        owl:onProperty ns1:hasTopping ;
                        owl:someValuesFrom ns1:CheeseTopping ] ) ] ;
    skos:definition "Any pizza that has at least 1 cheese topping."@en ;
    skos:prefLabel "Cheesy Pizza"@en .

ns1:Country a owl:Class ;
    rdfs:label "Country"@en,
        "Pais"@pt ;
    rdfs:comment "A class that is equivalent to the set of individuals that are described in the enumeration - ie Countries can only be either America, England, France, Germany or Italy and nothing else. Note that these individuals have been asserted to be allDifferent from each other."@en ;
    skos:prefLabel "Country"@en .

ns1:DeepPanBase a owl:Class ;
    rdfs:label "DeepPanBase"@en,
        "BaseEspessa"@pt ;
    rdfs:subClassOf ns1:PizzaBase ;
    owl:disjointWith ns1:ThinAndCrispyBase ;
    skos:prefLabel "Deep Pan Base"@en .

ns1:InterestingPizza a owl:Class ;
    rdfs:label "InterestingPizza"@en,
        "PizzaInteressante"@pt ;
    owl:equivalentClass [ a owl:Class ;
            owl:intersectionOf ( ns1:Pizza [ a owl:Restriction ;
                        owl:minCardinality "3"^^xsd:nonNegativeInteger ;
                        owl:onProperty ns1:hasTopping ] ) ] ;
    skos:definition "Any pizza that has at least 3 toppings. Note that this is a cardinality constraint on the hasTopping property and NOT a qualified cardinality constraint (QCR). A QCR would specify from which class the members in this relationship must be. eg has at least 3 toppings from PizzaTopping. This is currently not supported in OWL."@en ;
    skos:prefLabel "Interesting Pizza"@en .

ns1:MeatyPizza a owl:Class ;
    rdfs:label "MeatyPizza"@en,
        "PizzaDeCarne"@pt ;
    owl:equivalentClass [ a owl:Class ;
            owl:intersectionOf ( ns1:Pizza [ a owl:Restriction ;
                        owl:onProperty ns1:hasTopping ;
                        owl:someValuesFrom ns1:MeatTopping ] ) ] ;
    skos:definition "Any pizza that has at least one meat topping"@en ;
    skos:prefLabel "Meaty Pizza"@en .

ns1:NonVegetarianPizza a owl:Class ;
    rdfs:label "NonVegetarianPizza"@en,
        "PizzaNaoVegetariana"@pt ;
    owl:disjointWith ns1:VegetarianPizza ;
    owl:equivalentClass [ a owl:Class ;
            owl:intersectionOf ( ns1:Pizza [ a owl:Class ;
                        owl:complementOf ns1:VegetarianPizza ] ) ] ;
    skos:definition "Any Pizza that is not a VegetarianPizza"@en ;
    skos:prefLabel "Non Vegetarian Pizza"@en .

ns1:ParmaHamTopping a owl:Class ;
    rdfs:label "ParmaHamTopping"@en,
        "CoberturaDePrezuntoParma"@pt ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasSpiciness ;
            owl:someValuesFrom ns1:Mild ],
        ns1:HamTopping ;
    skos:prefLabel "Parma Ham"@en .

ns1:RealItalianPizza a owl:Class ;
    rdfs:label "RealItalianPizza"@en,
        "PizzaItalianaReal"@pt ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:allValuesFrom ns1:ThinAndCrispyBase ;
            owl:onProperty ns1:hasBase ] ;
    skos:definition "Any Pizza that has the country of origin, Italy.  RealItalianPizzas must also only have ThinAndCrispy bases."@en ;
    skos:prefLabel "Real Italian Pizza"@en .

ns1:SpicyPizza a owl:Class ;
    rdfs:label "SpicyPizza"@en,
        "PizzaTemperada"@pt ;
    owl:equivalentClass [ a owl:Class ;
            owl:intersectionOf ( ns1:Pizza [ a owl:Restriction ;
                        owl:onProperty ns1:hasTopping ;
                        owl:someValuesFrom ns1:SpicyTopping ] ) ] ;
    skos:definition "Any pizza that has a spicy topping is a SpicyPizza"@en ;
    skos:prefLabel "Spicy Pizza"@en .

ns1:SpicyPizzaEquivalent a owl:Class ;
    rdfs:label "SpicyPizzaEquivalent"@en,
        "PizzaTemperadaEquivalente"@pt ;
    rdfs:comment "An alternative definition for the SpicyPizza which does away with needing a definition of SpicyTopping and uses a slightly more complicated restriction: Pizzas that have at least one topping that is both a PizzaTopping and has spiciness hot are members of this class."@en ;
    owl:equivalentClass [ a owl:Class ;
            owl:intersectionOf ( ns1:Pizza [ a owl:Restriction ;
                        owl:onProperty ns1:hasTopping ;
                        owl:someValuesFrom [ a owl:Class ;
                                owl:intersectionOf ( ns1:PizzaTopping [ a owl:Restriction ;
                                            owl:onProperty ns1:hasSpiciness ;
                                            owl:someValuesFrom ns1:Hot ] ) ] ] ) ] ;
    skos:prefLabel "Spicy Pizza Equivalent"@en .

ns1:ThinAndCrispyPizza a owl:Class ;
    rdfs:label "ThinAndCrispyPizza"@en ;
    owl:equivalentClass [ a owl:Class ;
            owl:intersectionOf ( ns1:Pizza [ a owl:Restriction ;
                        owl:allValuesFrom ns1:ThinAndCrispyBase ;
                        owl:onProperty ns1:hasBase ] ) ] ;
    skos:prefLabel "Thin And Crispy Pizza"@en .

ns1:VegetarianPizzaEquivalent1 a owl:Class ;
    rdfs:label "VegetarianPizza1"@en,
        "PizzaVegetarianaEquivalente1"@pt ;
    rdfs:comment "Any pizza that only has vegetarian toppings or no toppings is a VegetarianPizzaEquiv1. Should be inferred to be equivalent to VegetarianPizzaEquiv2.  Not equivalent to VegetarianPizza because PizzaTopping is not covering"@en ;
    owl:equivalentClass [ a owl:Class ;
            owl:intersectionOf ( ns1:Pizza [ a owl:Restriction ;
                        owl:allValuesFrom ns1:VegetarianTopping ;
                        owl:onProperty ns1:hasTopping ] ) ] ;
    skos:prefLabel "Vegetarian Pizza1"@en .

ns1:VegetarianPizzaEquivalent2 a owl:Class ;
    rdfs:label "VegetarianPizza2"@en,
        "PizzaVegetarianaEquivalente2"@pt ;
    rdfs:comment "An alternative to VegetarianPizzaEquiv1 that does not require a definition of VegetarianTopping. Perhaps more difficult to maintain. Not equivalent to VegetarianPizza"@en ;
    owl:equivalentClass [ a owl:Class ;
            owl:intersectionOf ( ns1:Pizza [ a owl:Restriction ;
                        owl:allValuesFrom [ a owl:Class ;
                                owl:unionOf ( ns1:CheeseTopping ns1:FruitTopping ns1:HerbSpiceTopping ns1:NutTopping ns1:SauceTopping ns1:VegetableTopping ) ] ;
                        owl:onProperty ns1:hasTopping ] ) ] ;
    skos:prefLabel "Vegetarian Pizza2"@en .

ns1:hasCountryOfOrigin a owl:ObjectProperty ;
    owl:propertyDisjointWith ns1:hasSpiciness .

skos:altLabel a owl:AnnotationProperty .

skos:definition a owl:AnnotationProperty .

skos:prefLabel a owl:AnnotationProperty .

<http://www.co-ode.org/ontologies/pizza/LeekTopping_dynamic_1> a owl:NamedIndividual .

<http://www.co-ode.org/ontologies/pizza/MozzarellaTopping_dynamic_1> a owl:NamedIndividual .

<http://www.co-ode.org/ontologies/pizza/ParmesanTopping_dynamic_1> a owl:NamedIndividual .

<http://www.co-ode.org/ontologies/pizza/RosemaryTopping_dynamic_1> a owl:NamedIndividual .

<http://www.co-ode.org/ontologies/pizza/TomatoTopping_dynamic_1> a owl:NamedIndividual .

ns1:American a owl:Class ;
    rdfs:label "American"@en,
        "Americana"@pt ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:MozzarellaTopping ],
        [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:PeperoniSausageTopping ],
        [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:TomatoTopping ],
        [ a owl:Restriction ;
            owl:allValuesFrom [ a owl:Class ;
                    owl:unionOf ( ns1:MozzarellaTopping ns1:PeperoniSausageTopping ns1:TomatoTopping ) ] ;
            owl:onProperty ns1:hasTopping ],
        ns1:NamedPizza ;
    skos:altLabel "American"@en,
        "American Pizza"@en ;
    skos:prefLabel "American"@en .

ns1:AmericanHot a owl:Class ;
    rdfs:label "AmericanHot"@en,
        "AmericanaPicante"@pt ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:JalapenoPepperTopping ],
        [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:MozzarellaTopping ],
        [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:PeperoniSausageTopping ],
        [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:TomatoTopping ],
        [ a owl:Restriction ;
            owl:allValuesFrom [ a owl:Class ;
                    owl:unionOf ( ns1:HotGreenPepperTopping ns1:JalapenoPepperTopping ns1:MozzarellaTopping ns1:PeperoniSausageTopping ns1:TomatoTopping ) ] ;
            owl:onProperty ns1:hasTopping ],
        [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:HotGreenPepperTopping ],
        ns1:NamedPizza ;
    skos:altLabel "American Hot"@en,
        "American Hot Pizza"@en ;
    skos:prefLabel "American Hot"@en .

ns1:Cajun a owl:Class ;
    rdfs:label "Cajun"@en,
