ns1:Pizza a owl:Class ;
    rdfs:label "Pizza"@en ;
    rdfs:seeAlso <https://en.wikipedia.org/wiki/Pizza> ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasBase ;
            owl:someValuesFrom ns1:PizzaBase ],
        ns1:Food ;
    skos:prefLabel "Pizza"@en .

ns1:VegetableTopping a owl:Class ;
    rdfs:label "VegetableTopping"@en,
        "CoberturaDeVegetais"@pt ;
    rdfs:subClassOf ns1:PizzaTopping ;
    skos:prefLabel "Vegetable Topping"@en .

ns1:OliveTopping a owl:Class ;
    rdfs:label "OliveTopping"@en,
        "CoberturaDeAzeitona"@pt ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasSpiciness ;
            owl:someValuesFrom ns1:Mild ],
        ns1:VegetableTopping ;
    skos:prefLabel "Olive"@en .

ns1:NamedPizza a owl:Class ;
    rdfs:label "PizzaComUmNome"@pt ;
    rdfs:comment "A pizza that can be found on a pizza menu"@en ;
    rdfs:subClassOf ns1:Pizza .

ns1:Mild a owl:Class ;
    rdfs:label "Mild"@en,
        "NaoPicante"@pt ;
    rdfs:subClassOf ns1:Spiciness ;
    skos:prefLabel "Mild"@en .

ns1:hasSpiciness a owl:FunctionalProperty,
        owl:ObjectProperty ;
    rdfs:comment "A property created to be used with the ValuePartition - Spiciness."@en ;
    rdfs:range ns1:Spiciness .

ns1:MozzarellaTopping a owl:Class ;
    rdfs:label "MozzarellaTopping"@en,
        "CoberturaDeMozzarella"@pt ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasSpiciness ;
            owl:someValuesFrom ns1:Mild ],
        ns1:CheeseTopping ;
    skos:prefLabel "Mozzarella"@en .

ns1:TomatoTopping a owl:Class ;
    rdfs:label "TomatoTopping"@en,
        "CoberturaDeTomate"@pt ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasSpiciness ;
            owl:someValuesFrom ns1:Mild ],
        ns1:VegetableTopping ;
    skos:prefLabel "Tomato"@en .

ns1:hasTopping a owl:InverseFunctionalProperty,
        owl:ObjectProperty ;
    rdfs:comment "Note that hasTopping is inverse functional because isToppingOf is functional"@en ;
    rdfs:domain ns1:Pizza ;
    rdfs:range ns1:PizzaTopping ;
    rdfs:subPropertyOf ns1:hasIngredient ;
    owl:inverseOf ns1:isToppingOf .

[] a owl:AllDisjointClasses ;
    owl:members ( ns1:American ns1:AmericanHot ns1:Cajun ns1:Capricciosa ns1:Caprina ns1:Fiorentina ns1:FourSeasons ns1:FruttiDiMare ns1:Giardiniera ns1:LaReine ns1:Margherita ns1:Mushroom ns1:Napoletana ns1:Parmense ns1:PolloAdAstra ns1:PrinceCarlo ns1:QuattroFormaggi ns1:Rosa ns1:Siciliana ns1:SloppyGiuseppe ns1:Soho ns1:UnclosedPizza ns1:Veneziana ) .

[] a owl:AllDisjointClasses ;
    owl:members ( ns1:AnchoviesTopping ns1:MixedSeafoodTopping ns1:PrawnsTopping ) .

[] a owl:AllDisjointClasses ;
    owl:members ( ns1:ArtichokeTopping ns1:AsparagusTopping ns1:CaperTopping ns1:GarlicTopping ns1:LeekTopping ns1:MushroomTopping ns1:OliveTopping ns1:OnionTopping ns1:PepperTopping ns1:PetitPoisTopping ns1:RocketTopping ns1:SpinachTopping ns1:TomatoTopping ) .

[] a owl:AllDisjointClasses ;
    owl:members ( ns1:CheeseTopping ns1:FishTopping ns1:FruitTopping ns1:HerbSpiceTopping ns1:MeatTopping ns1:NutTopping ns1:SauceTopping ns1:VegetableTopping ) .

[] a owl:AllDisjointClasses ;
    owl:members ( ns1:ChickenTopping ns1:HamTopping ns1:HotSpicedBeefTopping ns1:PeperoniSausageTopping ) .

[] a owl:AllDisjointClasses ;
    owl:members ( ns1:FourCheesesTopping ns1:GoatsCheeseTopping ns1:GorgonzolaTopping ns1:MozzarellaTopping ns1:ParmesanTopping ) .

[] a owl:AllDisjointClasses ;
    owl:members ( ns1:GreenPepperTopping ns1:JalapenoPepperTopping ns1:PeperonataTopping ns1:SweetPepperTopping ) .

[] a owl:AllDisjointClasses ;
    owl:members ( ns1:Hot ns1:Medium ns1:Mild ) .

@prefix dc: <http://purl.org/dc/elements/1.1/> .
@prefix dcterms: <http://purl.org/dc/terms/> .
