        "CoberturaVegetariana"@pt ;
    rdfs:comment "An example of a covering axiom. VegetarianTopping is equivalent to the union of all toppings in the given axiom. VegetarianToppings can only be Cheese or Vegetable or....etc."@en ;
    owl:equivalentClass [ a owl:Class ;
            owl:intersectionOf ( ns1:PizzaTopping [ a owl:Class ;
                        owl:unionOf ( ns1:CheeseTopping ns1:FruitTopping ns1:HerbSpiceTopping ns1:NutTopping ns1:SauceTopping ns1:VegetableTopping ) ] ) ] ;
    skos:prefLabel "Vegetarian Topping"@en .

ns1:Veneziana a owl:Class ;
    rdfs:label "Veneziana"@en,
        "Veneziana"@pt ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:CaperTopping ],
        [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:MozzarellaTopping ],
        [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:OliveTopping ],
        [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:OnionTopping ],
        [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:PineKernels ],
        [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:SultanaTopping ],
        [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:TomatoTopping ],
        [ a owl:Restriction ;
            owl:allValuesFrom [ a owl:Class ;
                    owl:unionOf ( ns1:CaperTopping ns1:MozzarellaTopping ns1:OliveTopping ns1:OnionTopping ns1:PineKernels ns1:SultanaTopping ns1:TomatoTopping ) ] ;
            owl:onProperty ns1:hasTopping ],
        ns1:NamedPizza ;
    skos:altLabel "Veneziana"@en,
        "Veneziana Pizza"@en ;
    skos:prefLabel "Veneziana"@en .

ns1:isBaseOf a owl:FunctionalProperty,
