<http://www.co-ode.org/ontologies/pizza/Soho_8> a ns1:NamedPizza,
        owl:NamedIndividual ;
    ns1:hasTopping <http://www.co-ode.org/ontologies/pizza/GarlicTopping_dynamic_1>,
        <http://www.co-ode.org/ontologies/pizza/MozzarellaTopping_dynamic_1>,
        <http://www.co-ode.org/ontologies/pizza/OliveTopping_dynamic_1>,
        <http://www.co-ode.org/ontologies/pizza/ParmesanTopping_dynamic_1>,
