                        owl:onProperty ns1:hasTopping ;
                        owl:someValuesFrom ns1:MeatTopping ] ) ] ;
    skos:definition "Any pizza that has at least one meat topping"@en ;
    skos:prefLabel "Meaty Pizza"@en .

