    rdfs:label "InterestingPizza"@en,
        "PizzaInteressante"@pt ;
    owl:equivalentClass [ a owl:Class ;
            owl:intersectionOf ( ns1:Pizza [ a owl:Restriction ;
                        owl:minCardinality "3"^^xsd:nonNegativeInteger ;
                        owl:onProperty ns1:hasTopping ] ) ] ;
